def compute_outputs(f, g, t1, t2, o, v):
    tensor_map = {
        'f': f,
        'g': g,
    }
    get_view = _get_viewer(tensor_map, o, v)
    inter = compute_intermediates(get_view, t1, t2)
    I0 = inter['I0']
    I1 = inter['I1']
    I2 = inter['I2']
    I3 = inter['I3']
