    I79 = inter['I79']
    outputs = {}
    r1 = zeros_for_output('ai', o, v)
    r1 += (1.0) * np.einsum('ab,bi->ai', get_view('f', 'ab'), t1, optimize=True)
    r1 += (0.0625) * np.einsum('abij,bj->ai', t2, I45, optimize=True)
    r1 += (-0.0625) * np.einsum('abik,bk->ai', t2, I42, optimize=True)
    r1 += (-0.0625) * np.einsum('abji,bj->ai', t2, I45, optimize=True)
