    r1 += (-0.0625) * np.einsum('acij,cj->ai', t2, I46, optimize=True)
    r1 += (0.0625) * np.einsum('acik,ck->ai', t2, I43, optimize=True)
    r1 += (0.0625) * np.einsum('acji,cj->ai', t2, I46, optimize=True)
    r1 += (-0.0625) * np.einsum('acjk,cijk->ai', t2, I41, optimize=True)
    r1 += (-0.0625) * np.einsum('acki,ck->ai', t2, I43, optimize=True)
    r1 += (0.0625) * np.einsum('ackj,cijk->ai', t2, I41, optimize=True)
    r1 += (0.08333333333333333) * np.einsum('ai,bj,bj->ai', t1, t1, I45, optimize=True)
    r1 += (-0.08333333333333333) * np.einsum('ai,bk,bk->ai', t1, t1, I42, optimize=True)
