    r1 += (-0.041666666666666664) * np.einsum('aj,bi,bj->ai', t1, t1, I45, optimize=True)
    r1 += (0.041666666666666664) * np.einsum('aj,bk,bijk->ai', t1, t1, I40, optimize=True)
    r1 += (0.041666666666666664) * np.einsum('aj,ci,cj->ai', t1, t1, I46, optimize=True)
    r1 += (-0.041666666666666664) * np.einsum('aj,ck,cijk->ai', t1, t1, I41, optimize=True)
    r1 += (0.0625) * np.einsum('ajbc,bcij->ai', get_view('g', 'ajbc'), t2, optimize=True)
