    r1 += (-0.0625) * np.einsum('ajbc,cbij->ai', get_view('g', 'ajbc'), t2, optimize=True)
    r1 += (0.0625) * np.einsum('ajbc,cbji->ai', get_view('g', 'ajbc'), t2, optimize=True)
    r1 += (-0.125) * np.einsum('ajbc,ci,bj->ai', get_view('g', 'ajbc'), t1, t1, optimize=True)
