    r1 += (-0.041666666666666664) * np.einsum('ak,bj,bijk->ai', t1, t1, I40, optimize=True)
    r1 += (-0.041666666666666664) * np.einsum('ak,ci,ck->ai', t1, t1, I43, optimize=True)
    r1 += (0.041666666666666664) * np.einsum('ak,cj,cijk->ai', t1, t1, I41, optimize=True)
    r1 += (-0.0625) * np.einsum('baij,bj->ai', t2, I45, optimize=True)
    r1 += (0.0625) * np.einsum('baik,bk->ai', t2, I42, optimize=True)
    r1 += (0.0625) * np.einsum('baji,bj->ai', t2, I45, optimize=True)
