    r1 += (0.0625) * np.einsum('bcij,abcj->ai', t2, I47, optimize=True)
    r1 += (-0.0625) * np.einsum('bcik,abck->ai', t2, I44, optimize=True)
    r1 += (-0.0625) * np.einsum('bcji,abcj->ai', t2, I47, optimize=True)
    r1 += (0.0625) * np.einsum('bcki,abck->ai', t2, I44, optimize=True)
    r1 += (-0.041666666666666664) * np.einsum('bi,aj,bj->ai', t1, t1, I45, optimize=True)
    r1 += (0.041666666666666664) * np.einsum('bi,ak,bk->ai', t1, t1, I42, optimize=True)
    r1 += (0.041666666666666664) * np.einsum('bi,cj,abcj->ai', t1, t1, I47, optimize=True)
    r1 += (-0.041666666666666664) * np.einsum('bi,ck,abck->ai', t1, t1, I44, optimize=True)
    r1 += (0.041666666666666664) * np.einsum('bj,ai,bj->ai', t1, t1, I45, optimize=True)
    r1 += (-0.041666666666666664) * np.einsum('bj,ak,bijk->ai', t1, t1, I40, optimize=True)
    r1 += (-0.041666666666666664) * np.einsum('bj,ci,abcj->ai', t1, t1, I47, optimize=True)
    r1 += (-0.041666666666666664) * np.einsum('bk,ai,bk->ai', t1, t1, I42, optimize=True)
